import pandas as pd
urls = {
'Kentucky':'https://fred.stlouisfed.org/graph/fredgraph.csv?id=MEDLISPRIKY',
'Arizona':'https://fred.stlouisfed.org/graph/fredgraph.csv?id=MEDLISPRIAZ',
'South Carolina':'https://fred.stlouisfed.org/graph/fredgraph.csv?id=MEDLISPRISC',
'Kansas':'https://fred.stlouisfed.org/graph/fredgraph.csv?id=MEDLISPRIKS',
}
for state,url in urls.items():
    try:
        df=pd.read_csv(url)
        row=df[df['DATE']=='2023-01-01']
        print(state, row.iloc[0,1] if not row.empty else 'no jan 2023')
    except Exception as e:
        print(state, 'ERR', e)
